with cleaned as (select id, order_id, method, amount, paid_at, lower(method) method_lower, case when method = 'bank_transfer' then 1 else 0 end is_bank_transfer from payments where paid_at >= date '2023-08-27' and method = 'promptpay') select id, paid_at, method_lower, is_bank_transfer from cleaned qualify rank() over (partition by order_id, method order by is_bank_transfer nulls last) = 1;
